import React, { useState } from "react";
import IncomeCategory from "./components/IncomeCategory";
import Questionnaire from "./components/Questionnaire";
import SpendingPriority from "./components/SpendingPriority";
import BudgetLimits from "./components/BudgetLimits";

function AppRouter() {
  const [step, setStep] = useState(1);

  const [formData, setFormData] = useState({
    incomeCategory: "",
    questionnaire: {},
    spendingPriorities: {},
    budgetLimits: {}
  });

  const updateData = (data) => {
    setFormData((prev) => ({ ...prev, ...data }));
  };

  const nextStep = () => setStep((prev) => prev + 1);

  if (step === 1)
    return <IncomeCategory onNext={nextStep} updateData={updateData} />;

  if (step === 2)
    return <Questionnaire onNext={nextStep} updateData={updateData} />;

  if (step === 3)
    return (
      <SpendingPriority
        onNext={nextStep}
        updateData={updateData}
        formData={formData}
      />
    );

  if (step === 4)
    return (
      <BudgetLimits
        formData={formData}
        updateData={updateData}
      />
    );

  return null;
}

export default AppRouter;
